        let opus = try ExportOpusEncoder(bitRate: ExportOpusEncoder.defaultBitRate)
        _ = try opus.encode(sample)
        return (opus.framesFed, nil)
    } catch Exporter.ExportError.failed(let text) {
        return (nil, text)
    } catch {
        return (nil, "\(error)")
    }
