}
let a1Sample = buffer(samples: 1_000, at: 500)
let a1 = place(a1Sample, at: 500)
check("A1 a buffer at frame 500 with nothing written: 500 frames of zeros, then the buffer",
      frames(a1) == [500, 1_000] && silent(a1[0]) && a1[1] === a1Sample && end.written == 1_500,
      "placed \(frames(a1)), the first silent \(a1.first.map(silent) ?? false), the second the "
        + "buffer itself \(a1.count == 2 && a1[1] === a1Sample); written \(end.written)")
let a2 = place(buffer(samples: 300, at: 1_400), at: 1_400)
check("A2 a 300-frame buffer at frame 1,400: its last 200 frames, from its frame 100",
      frames(a2) == [200] && a2.first.flatMap(firstLeft) == 100 && end.written == 1_700,
      "placed \(frames(a2)), first left sample \(a2.first.flatMap(firstLeft).map(String.init) ?? "nil") "
        + "(want 100); written \(end.written)")
let a3 = place(buffer(samples: 300, at: 1_000), at: 1_000)
check("A3 a 300-frame buffer at frame 1,000 (covered whole): nothing",
      a3.isEmpty && end.written == 1_700, "placed \(frames(a3)); written \(end.written)")
let a4Sample = buffer(samples: 300, at: 1_700)
let a4 = place(a4Sample, at: 1_700)
check("A4 a buffer at frame 1,700 (no gap): the buffer itself",
      frames(a4) == [300] && a4.first === a4Sample && end.written == 2_000,
      "placed \(frames(a4)); written \(end.written)")

// A5 — the gap's zeros stop at the target.
do {
    let short = ExportAudioEnd(range: range(frames: 2_000))
    let lead = buffer(samples: 1_500).flatMap { short.fit($0) }
    let gap = buffer(samples: 100, at: 5_000).map { short.align($0, at: 5_000) } ?? []
    let zeros = gap.dropLast().reduce(0) { $0 + CMSampleBufferGetNumSamples($1) }
    check("A5 a 2,000-frame target, 1,500 written, a buffer at frame 5,000: 500 frames of zeros",
          lead != nil && zeros == 500 && gap.count >= 2,
          "the lead fitted \(lead != nil); placed \(frames(gap)), zeros \(zeros) (want 500)")
}

let answer = try JSONSerialization.data(withJSONObject: ["rows": rows], options: [.prettyPrinted])
if CommandLine.arguments.count > 1 {
    try answer.write(to: URL(fileURLWithPath: CommandLine.arguments[1]))
